package com.ironkinclan.manager;

import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanChannel;

/**
 * Reports on the nearby player group at a kill: who else is there, and how many of them are
 * members of the local player's in-game Clan, for features (like group boss submissions) that
 * need to know who was present and whether the clan made up the group.
 */
public class ClanMemberManager
{
	private final Client client;

	@Inject
	public ClanMemberManager(Client client)
	{
		this.client = client;
	}

	// Reads the top-level WorldView's players and the clan channel, so must be called on the
	// client thread.
	public GroupComposition getNearbyGroupComposition()
	{
		ClanChannel clanChannel = client.getClanChannel();
		Player localPlayer = client.getLocalPlayer();
		String localName = localPlayer == null ? null : localPlayer.getName();

		int totalPlayers = 0;
		int clanPlayers = 0;
		List<String> clanMembers = new ArrayList<>();

		for (Player player : client.getTopLevelWorldView().players())
		{
			String name = player.getName();
			if (name == null)
			{
				continue;
			}

			totalPlayers++;

			if (clanChannel == null || clanChannel.findMember(name) == null)
			{
				continue;
			}

			clanPlayers++;
			if (!name.equals(localName))
			{
				clanMembers.add(name);
			}
		}

		return new GroupComposition(totalPlayers, clanPlayers, clanMembers);
	}
}

package com.ironkinclan.manager;

import com.ironkinclan.model.BossActivity;
import net.runelite.api.Actor;
import net.runelite.api.NPC;

/**
 * Tracks which {@link BossActivity} the local player most recently engaged in combat with.
 * RuneScape's "new personal best" chat message rarely names the boss itself, so this is
 * used to attribute that message to the right activity when it arrives.
 */
public class CurrentBossTracker
{
	private BossActivity currentBoss;

	// OSRS sets "interacting" inconsistently depending on who initiates combat, so both
	// directions (player attacking the NPC, or the NPC attacking the player) are checked.
	public void onInteractingChanged(Actor localPlayer, Actor source, Actor target)
	{
		NPC npc;
		if (source == localPlayer && target instanceof NPC)
		{
			npc = (NPC) target;
		}
		else if (target == localPlayer && source instanceof NPC)
		{
			npc = (NPC) source;
		}
		else
		{
			return;
		}

		BossActivity activity = BossActivity.forNpcName(npc.getName());
		if (activity != null)
		{
			currentBoss = activity;
		}
	}

	public BossActivity getCurrentBoss()
	{
		return currentBoss;
	}

	public void reset()
	{
		currentBoss = null;
	}
}

