public interface DiagnosticListener
{
	void onDiagnosticEvent(String text, boolean success);
}

package com.ironkinclan.manager;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import com.ironkinclan.api.IronkinClanApiClient;
import com.ironkinclan.api.RequestSummary;
import com.ironkinclan.api.ResponsePreview;
import com.ironkinclan.api.RetryingCall;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.Base64;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.DrawManager;
import net.runelite.client.util.ImageUtil;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Captures a screenshot of a tracked item drop and uploads it to the Ironkin server.
 */
@Slf4j
public class DropSubmissionManager
{
	private final IronkinClanApiClient apiClient;
	private final OkHttpClient httpClient;
	private final Gson gson;
	private final DrawManager drawManager;
	private final ScheduledExecutorService executor;

	@Inject
	public DropSubmissionManager(IronkinClanApiClient apiClient, OkHttpClient httpClient, Gson gson,
		DrawManager drawManager, ScheduledExecutorService executor)
	{
		this.apiClient = apiClient;
		this.httpClient = httpClient;
		this.gson = gson;
		this.drawManager = drawManager;
		this.executor = executor;
	}

	private DiagnosticListener listener;
	private DiagnosticListener diagnosticListener;
	private RemoteLogListener remoteLogListener;

	public void setListener(DiagnosticListener listener)
	{
		this.listener = listener;
	}

	// Separate from listener: receives background detail (encoding, retries) that belongs in the
	// panel log only, whereas listener carries the submission results that are also echoed to chat.
	public void setDiagnosticListener(DiagnosticListener diagnosticListener)
	{
		this.diagnosticListener = diagnosticListener;
	}

	// Unlike the two listeners above, what goes here leaves the machine, so it never gets the
	// username, the participants, the screenshot or the headers.
	public void setRemoteLogListener(RemoteLogListener remoteLogListener)
	{
		this.remoteLogListener = remoteLogListener;
	}

	public void reportDrop(String eventId, String username, int itemId, String itemName)
	{
		reportDrop(eventId, username, itemId, itemName, Collections.emptyList());
	}

	// participants is the set of other nearby clan members to credit alongside username - only
	// populated for group boss kills (see GroupBossRegistry), empty otherwise.
	public void reportDrop(String eventId, String username, int itemId, String itemName, List<String> participants)
	{
		long timestamp = System.currentTimeMillis();
		drawManager.requestNextFrameListener(image -> executor.execute(() -> uploadDrop(eventId, username, itemId, itemName, timestamp, participants, image)));
	}

	// Package-private (rather than private) so unit tests can exercise the encode/upload logic
	// directly without needing to drive the DrawManager frame-capture pipeline.
	void uploadDrop(String eventId, String username, int itemId, String itemName, long timestamp, List<String> participants, Image image)
	{
		String imageData;
		try
		{
			BufferedImage screenshot = ImageUtil.bufferedImageFromImage(image);
			ByteArrayOutputStream baos = new ByteArrayOutputStream();
			ImageIO.write(screenshot, "png", baos);
			imageData = Base64.getEncoder().encodeToString(baos.toByteArray());
		}
		catch (IOException e)
		{
			log.warn("Failed to encode Ironkin drop screenshot for item {}", itemId, e);
			notifyListener("Failed to capture screenshot for " + itemName, false);
			notifyRemote(RemoteLogListener.Level.ERROR, "Failed to encode drop screenshot",
				Map.of("eventId", eventId, "itemId", itemId, "exception", e.toString()));
			return;
		}

		notifyDiagnostic("Encoded " + itemName + " drop screenshot for " + username + ": " + imageData.length() + " base64 chars", true);
		notifyListener("Captured screenshot for " + itemName + " drop", true);

		DropReport report = new DropReport(username, itemId, timestamp, imageData, participants);
		RequestBody body = RequestBody.create(IronkinClanApiClient.JSON, gson.toJson(report));
		// What gets written to the panel log if the upload fails: the same body, but with the
		// screenshot replaced by its size, since the base64 payload would swamp an exported log.
		String loggedBody = gson.toJson(new DropReport(username, itemId, timestamp,
			"[base64 PNG, " + imageData.length() + " chars]", participants));

		Request request = apiClient.newSubmissionRequest(eventId)
			.post(body)
			.build();

		// What goes to the logging service if the upload fails: the request without the screenshot
		// and without the player names (username, participants), which must not leave the machine.
		Map<String, Object> reportedRequest = RequestSummary.of(request,
			Map.of("itemid", itemId, "timestamp", timestamp, "participantCount", participants.size()));

		RetryingCall.enqueue(httpClient, executor, request, message -> notifyDiagnostic(message, false), new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("Failed to upload Ironkin drop report for item {} to event {}", itemId, eventId, e);
				notifyListener("Failed to send " + itemName + " drop to " + eventId + ": " + e.getMessage(), false);
				notifyFailedRequest(request, loggedBody);
				notifyRemote(RemoteLogListener.Level.ERROR, "Failed to upload drop",
					Map.of("eventId", eventId, "itemId", itemId, "exception", e.toString(), "request", reportedRequest));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (!r.isSuccessful())
					{
						log.warn("Ironkin drop report upload failed for item {} to event {}: HTTP {}", itemId, eventId, r.code());
						notifyListener("Failed to send " + itemName + " drop to " + eventId + " (HTTP " + r.code() + ")", false);
						notifyFailedRequest(request, loggedBody);
						String serverResponse = ResponsePreview.of(r);
						notifyDiagnostic("Server response (HTTP " + r.code() + "): " + serverResponse, false);
						notifyRemote(RemoteLogListener.Level.ERROR, "Drop upload returned an HTTP error",
							Map.of("eventId", eventId, "itemId", itemId, "httpStatus", r.code(),
								"request", reportedRequest, "response", serverResponse));
					}
					else
					{
						notifyListener("Sent " + itemName + " drop for " + username + " to " + eventId, true);
					}
				}
			}
		});
	}

	private void notifyListener(String text, boolean success)
	{
		if (listener != null)
		{
			listener.onDiagnosticEvent(text, success);
		}
	}

	// Deliberately logs the method, URL and body only - never the headers, which carry the API key.
	private void notifyFailedRequest(Request request, String loggedBody)
	{
		notifyDiagnostic("Failed request was " + request.method() + " " + request.url() + " with body: " + loggedBody, false);
	}

	private void notifyDiagnostic(String text, boolean success)
	{
		if (diagnosticListener != null)
		{
			diagnosticListener.onDiagnosticEvent(text, success);
		}
	}

	private void notifyRemote(RemoteLogListener.Level level, String message, Map<String, Object> context)
	{
		if (remoteLogListener != null)
		{
			remoteLogListener.onRemoteLogEvent(level, message, context);
		}
	}

	private static class DropReport
	{
		@SerializedName("username")
		final String username;
		@SerializedName("itemid")
		final int itemId;
		@SerializedName("timestamp")
		final long timestamp;
		@SerializedName("imageData")
		final String imageData;
		@SerializedName("participants")
		final List<String> participants;

		DropReport(String username, int itemId, long timestamp, String imageData, List<String> participants)
		{
			this.username = username;
			this.itemId = itemId;
			this.timestamp = timestamp;
			this.imageData = imageData;
			this.participants = participants;
		}
	}
}

package com.ironkinclan.manager;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.ironkinclan.api.IronkinClanApiClient;
import com.ironkinclan.api.RequestSummary;
import com.ironkinclan.api.ResponsePreview;
import com.ironkinclan.config.IronkinClanConfig;
import java.io.IOException;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Polls the member's ember balance on a fixed interval. Unlike {@link TrackedItemManager}, this
 * intentionally does not use {@link com.ironkinclan.api.RetryingCall}: a failed poll is
 * superseded by the next scheduled poll a few minutes later anyway, so retrying just adds delay
 * without adding value.
 */
@Slf4j
public class EmberManager
{
	private static final long POLL_INTERVAL_MINUTES = 5;

	public interface Listener
	{
		// delta is the change since the last successful poll, or null if this is the first poll
		// or the balance hasn't changed.
		void onEmberBalanceUpdated(int balance, Integer delta);
	}

	private final IronkinClanConfig config;
	private final IronkinClanApiClient apiClient;
	private final OkHttpClient httpClient;
	private final Gson gson;
	private final ScheduledExecutorService executor;

	private volatile Integer lastBalance;
	private ScheduledFuture<?> pollTask;

	private Listener listener;
	private DiagnosticListener diagnosticListener;
	private RemoteLogListener remoteLogListener;

	@Inject
	public EmberManager(IronkinClanConfig config, IronkinClanApiClient apiClient, OkHttpClient httpClient,
		Gson gson, ScheduledExecutorService executor)
	{
		this.config = config;
		this.apiClient = apiClient;
		this.httpClient = httpClient;
		this.gson = gson;
		this.executor = executor;
	}

	public void setListener(Listener listener)
	{
		this.listener = listener;
	}

	public void setDiagnosticListener(DiagnosticListener diagnosticListener)
	{
		this.diagnosticListener = diagnosticListener;
	}

	public void setRemoteLogListener(RemoteLogListener remoteLogListener)
	{
		this.remoteLogListener = remoteLogListener;
	}

	public void start()
	{
		stop();
		fetch();
		pollTask = executor.scheduleAtFixedRate(this::fetch, POLL_INTERVAL_MINUTES, POLL_INTERVAL_MINUTES, TimeUnit.MINUTES);
	}

	public void stop()
	{
		if (pollTask != null)
		{
			pollTask.cancel(false);
			pollTask = null;
		}
	}

	public void reset()
	{
		lastBalance = null;
	}

	public void fetch()
	{
		if (config.serverUrl().isEmpty() || config.apiKey().isEmpty())
		{
			return;
		}

		Request request = apiClient.newEmberBalanceRequest().build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				warn("Failed to fetch Ironkin ember balance: " + e.getMessage(), e);
				notifyRemote(RemoteLogListener.Level.WARN, "Failed to fetch ember balance",
					Map.of("exception", e.toString(), "request", RequestSummary.of(request, null)));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				EmberBalanceResponse body;
				try (Response r = response)
				{
					if (!r.isSuccessful() || r.body() == null)
					{
						String serverResponse = ResponsePreview.of(r);
						warn("Failed to fetch Ironkin ember balance: HTTP " + r.code() + " - server response: " + serverResponse);
						notifyRemote(RemoteLogListener.Level.WARN, "Ember balance fetch returned an HTTP error",
							Map.of("httpStatus", r.code(), "request", RequestSummary.of(request, null), "response", serverResponse));
						return;
					}

					body = gson.fromJson(r.body().charStream(), EmberBalanceResponse.class);
					if (body == null)
					{
						warn("Ironkin ember balance response was empty or malformed");
						notifyRemote(RemoteLogListener.Level.WARN, "Ember balance response was empty or malformed", null);
						return;
					}
				}
				catch (JsonSyntaxException e)
				{
					warn("Failed to parse Ironkin ember balance: " + e.getMessage(), e);
					notifyRemote(RemoteLogListener.Level.WARN, "Failed to parse ember balance", Map.of("exception", e.toString()));
					return;
				}

				Integer previousBalance = lastBalance;
				lastBalance = body.balance;

				Integer delta = (previousBalance != null && previousBalance != body.balance)
					? body.balance - previousBalance
					: null;

				if (diagnosticListener != null)
				{
					diagnosticListener.onDiagnosticEvent(
						"Ember balance updated: " + body.balance + " (previous: " + previousBalance + ")", true);
				}

				if (listener != null)
				{
					listener.onEmberBalanceUpdated(body.balance, delta);
				}
			}
		});
	}

	private void warn(String message)
	{
		log.warn(message);
		if (diagnosticListener != null)
		{
			diagnosticListener.onDiagnosticEvent(message, false);
		}
	}

	private void warn(String message, Throwable t)
	{
		log.warn(message, t);
		if (diagnosticListener != null)
		{
			diagnosticListener.onDiagnosticEvent(message, false);
		}
	}

	private void notifyRemote(RemoteLogListener.Level level, String message, Map<String, Object> context)
	{
		if (remoteLogListener != null)
		{
			remoteLogListener.onRemoteLogEvent(level, message, context);
		}
	}

	private static class EmberBalanceResponse
	{
		int balance;
	}
}

package com.ironkinclan.manager;

import java.util.ArrayList;
import java.util.List;

/**
 * Snapshot of the nearby player group at the moment of a drop: how many players are present in
 * total, how many of them are in the local player's clan, and their names (excluding the local
 * player, who is implied to be one of clanPlayers if the local player is themselves in the clan).
 */
public class GroupComposition
{
	public final int totalPlayers;
	public final int clanPlayers;
	public final List<String> clanMembers;

	public GroupComposition(int totalPlayers, int clanPlayers, List<String> clanMembers)
	{
		this.totalPlayers = totalPlayers;
		this.clanPlayers = clanPlayers;
		this.clanMembers = clanMembers;
	}

	// Adds the clan members of the raid party who are not standing nearby any more (see
	// RaidPartyTracker), so they count towards eligibility and are credited as participants.
	public GroupComposition withRaidClanMembers(List<String> raidClanMembers)
	{
		List<String> merged = new ArrayList<>(clanMembers);
		for (String name : raidClanMembers)
		{
			if (!merged.contains(name))
			{
				merged.add(name);
			}
		}

		int added = merged.size() - clanMembers.size();
		return new GroupComposition(totalPlayers + added, clanPlayers + added, merged);
	}

	// At least one other clan member must be nearby. Solo kills never qualify - clanPlayers must
	// include the local player plus at least one more.
	public boolean hasClanBackup()
	{
		return clanPlayers > 1;
	}
}

package com.ironkinclan.manager;

import com.ironkinclan.api.IronkinClanApiClient;
import com.ironkinclan.api.RequestSummary;
import com.ironkinclan.api.ResponsePreview;
import com.ironkinclan.api.RetryingCall;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import net.runelite.client.ui.DrawManager;
import net.runelite.client.util.ImageUtil;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Captures a screenshot of a new personal best and uploads it to the Ironkin Hall of Flame.
 */
public class PersonalBestManager
{
	private static final MediaType PNG = MediaType.get("image/png");

	private final IronkinClanApiClient apiClient;
	private final OkHttpClient httpClient;
	private final DrawManager drawManager;
	private final ScheduledExecutorService executor;

	@Inject
	public PersonalBestManager(IronkinClanApiClient apiClient, OkHttpClient httpClient,
		DrawManager drawManager, ScheduledExecutorService executor)
	{
		this.apiClient = apiClient;
		this.httpClient = httpClient;
		this.drawManager = drawManager;
		this.executor = executor;
	}

	private DiagnosticListener listener;
	private DiagnosticListener diagnosticListener;
	private RemoteLogListener remoteLogListener;

	public void setListener(DiagnosticListener listener)
	{
		this.listener = listener;
	}

	// Separate from listener: receives background detail (retries) that belongs in the panel log
	// only, whereas listener carries the submission results that are also echoed to chat.
	public void setDiagnosticListener(DiagnosticListener diagnosticListener)
	{
		this.diagnosticListener = diagnosticListener;
	}

	// Unlike the two listeners above, what goes here leaves the machine, so it never gets the
	// username, the screenshot or the headers.
	public void setRemoteLogListener(RemoteLogListener remoteLogListener)
	{
		this.remoteLogListener = remoteLogListener;
	}

	public void reportPersonalBest(String username, String bossName, String time)
	{
		drawManager.requestNextFrameListener(image -> executor.execute(() -> uploadPersonalBest(username, bossName, time, image)));
	}

	// Package-private (rather than private) so unit tests can exercise the encode/upload logic
	// directly without needing to drive the DrawManager frame-capture pipeline.
	void uploadPersonalBest(String username, String bossName, String time, Image image)
	{
		byte[] pngBytes;
		try
		{
			BufferedImage screenshot = ImageUtil.bufferedImageFromImage(image);
			ByteArrayOutputStream baos = new ByteArrayOutputStream();
			ImageIO.write(screenshot, "png", baos);
			pngBytes = baos.toByteArray();
		}
		catch (IOException e)
		{
			notifyListener("Failed to capture screenshot for " + bossName + " personal best", false);
			notifyRemote(RemoteLogListener.Level.ERROR, "Failed to encode personal best screenshot",
				Map.of("boss", bossName, "exception", e.toString()));
			return;
		}

		MultipartBody body = new MultipartBody.Builder()
			.setType(MultipartBody.FORM)
			.addFormDataPart("player", username)
			.addFormDataPart("boss", bossName)
			.addFormDataPart("time", time)
			.addFormDataPart("proof", "personal-best.png", RequestBody.create(PNG, pngBytes))
			.build();

		// What gets written to the panel log if the upload fails: the form fields, with the
		// screenshot replaced by its size, since the image bytes would swamp an exported log.
		String loggedBody = "player=" + username + ", boss=" + bossName + ", time=" + time
			+ ", proof=[PNG, " + pngBytes.length + " bytes]";

		Request request = apiClient.newPersonalBestRequest()
			.post(body)
			.build();

		// What goes to the logging service if the upload fails: the form fields without the proof
		// image and without the player name, which must not leave the machine.
		Map<String, Object> reportedRequest = RequestSummary.of(request, Map.of("boss", bossName, "time", time));

		RetryingCall.enqueue(httpClient, executor, request, message -> notifyDiagnostic(message, false), new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				notifyListener("Failed to send " + bossName + " personal best (" + time + "): " + e.getMessage(), false);
				notifyFailedRequest(request, loggedBody);
				notifyRemote(RemoteLogListener.Level.ERROR, "Failed to upload personal best",
					Map.of("boss", bossName, "time", time, "exception", e.toString(), "request", reportedRequest));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (!r.isSuccessful())
					{
						notifyListener("Failed to send " + bossName + " personal best (HTTP " + r.code() + ")", false);
						notifyFailedRequest(request, loggedBody);
						String serverResponse = ResponsePreview.of(r);
						notifyDiagnostic("Server response (HTTP " + r.code() + "): " + serverResponse, false);
						notifyRemote(RemoteLogListener.Level.ERROR, "Personal best upload returned an HTTP error",
							Map.of("boss", bossName, "time", time, "httpStatus", r.code(),
								"request", reportedRequest, "response", serverResponse));
					}
					else
					{
						notifyListener("Sent " + bossName + " personal best (" + time + ") for " + username, true);
					}
				}
			}
		});
	}

	private void notifyListener(String text, boolean success)
	{
		if (listener != null)
		{
			listener.onDiagnosticEvent(text, success);
		}
	}

	// Deliberately logs the method, URL and body only - never the headers, which carry the API key.
	private void notifyFailedRequest(Request request, String loggedBody)
	{
		notifyDiagnostic("Failed request was " + request.method() + " " + request.url() + " with body: " + loggedBody, false);
	}

	private void notifyDiagnostic(String text, boolean success)
	{
		if (diagnosticListener != null)
		{
			diagnosticListener.onDiagnosticEvent(text, success);
		}
	}

	private void notifyRemote(RemoteLogListener.Level level, String message, Map<String, Object> context)
	{
		if (remoteLogListener != null)
		{
			remoteLogListener.onRemoteLogEvent(level, message, context);
		}
	}
}

package com.ironkinclan.manager;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.util.Text;

/**
 * Recognizes RuneScape's "new personal best" game message (e.g. "Fight duration: 1:23.40
 * (new personal best)." or "Fight duration: 0:35 (new personal best).") and extracts the
 * completion time from it. This is the only client-side signal available for a new PB -
 * RuneLite can't read server-stored PB data directly.
 */
public final class PersonalBestMessageParser
{
	private static final String PB_MARKER = "new personal best";
	// The centisecond portion is optional - very short fights (e.g. "0:35") are reported
	// without one, confirmed against a real Shellbane Gryphon kill message in-game.
	private static final Pattern TIME_PATTERN = Pattern.compile("(\\d{1,3}:\\d{2}(?:\\.\\d{1,2})?)");

	private PersonalBestMessageParser()
	{
	}

	/**
	 * @return the completion time (e.g. "1:23.40") if {@code rawMessage} announces a new
	 * personal best, or {@code null} otherwise.
	 */
	public static String parseTime(String rawMessage)
	{
		if (rawMessage == null)
		{
			return null;
		}

		String message = Text.removeTags(rawMessage);
		if (!message.toLowerCase().contains(PB_MARKER))
		{
			return null;
		}

		Matcher matcher = TIME_PATTERN.matcher(message);
		return matcher.find() ? matcher.group(1) : null;
	}
}

package com.ironkinclan.manager;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.util.Text;

/**
 * Remembers who the local player raided with, for the whole length of the raid. A raid's loot
 * arrives when the reward chest is opened, by which point teammates have often already left, so
 * the players standing nearby at that moment say little about who was actually in the raid.
 *
 * Theatre of Blood and Tombs of Amascut publish the party's names to the client. Chambers of Xeric
 * does not (only the party size), but its dungeon is private to the party, so every player seen
 * inside it is a party member.
 *
 * Each raid keeps its own party, replaced only when that raid is entered again. Leaving the raid
 * or the party does not forget it, because unclaimed loot can still be collected from the chest
 * in the lobby afterwards.
 *
 * Everything here runs on the client thread.
 */
public class RaidPartyTracker
{
	private static final String CHAMBERS_OF_XERIC = "Chambers of Xeric";
	private static final String THEATRE_OF_BLOOD = "Theatre of Blood";
	private static final String TOMBS_OF_AMASCUT = "Tombs of Amascut";

	// TOB_CLIENT_PARTYSTATUS: 0 = no party, 1 = in a party outside, 2 = inside, 3 = dead inside.
	// TOA_CLIENT_PARTYSTATUS is assumed to follow the same scheme.
	private static final int STATUS_INSIDE = 2;

	private static final int[] TOB_NAME_VARCS = {
		VarClientID.TOB_CLIENT_NAME0,
		VarClientID.TOB_CLIENT_NAME1,
		VarClientID.TOB_CLIENT_NAME2,
		VarClientID.TOB_CLIENT_NAME3,
		VarClientID.TOB_CLIENT_NAME4
	};

	private static final int[] TOA_NAME_VARCS = {
		VarClientID.TOA_CLIENT_NAME0,
		VarClientID.TOA_CLIENT_NAME1,
		VarClientID.TOA_CLIENT_NAME2,
		VarClientID.TOA_CLIENT_NAME3,
		VarClientID.TOA_CLIENT_NAME4,
		VarClientID.TOA_CLIENT_NAME5,
		VarClientID.TOA_CLIENT_NAME6,
		VarClientID.TOA_CLIENT_NAME7
	};

	private final Client client;

	private final Party chambersParty = new Party();
	private final Party theatreParty = new Party();
	private final Party tombsParty = new Party();

	private boolean inChambers;
	private int tobStatus;
	private int toaStatus;

	@Inject
	public RaidPartyTracker(Client client)
	{
		this.client = client;
	}

	// Loot Tracker reports raid chests under these names.
	public static boolean isRaidLoot(String lootSource)
	{
		return CHAMBERS_OF_XERIC.equals(lootSource)
			|| THEATRE_OF_BLOOD.equals(lootSource)
			|| TOMBS_OF_AMASCUT.equals(lootSource);
	}

	// Picks up a raid already in progress, for when tracking starts part-way through one.
	public void sync()
	{
		onVarbitChanged(VarbitID.RAIDS_CLIENT_INDUNGEON, client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON));
		onVarbitChanged(VarbitID.TOB_CLIENT_PARTYSTATUS, client.getVarbitValue(VarbitID.TOB_CLIENT_PARTYSTATUS));
		onVarbitChanged(VarbitID.TOA_CLIENT_PARTYSTATUS, client.getVarbitValue(VarbitID.TOA_CLIENT_PARTYSTATUS));
	}

	public void onVarbitChanged(int varbitId, int value)
	{
		switch (varbitId)
		{
			case VarbitID.RAIDS_CLIENT_INDUNGEON:
				boolean inside = value > 0;
				if (inside && !inChambers)
				{
					chambersParty.clear();
					recordVisiblePlayers();
				}
				inChambers = inside;
				break;
			case VarbitID.TOB_CLIENT_PARTYSTATUS:
				tobStatus = onPartyStatusChanged(tobStatus, value, TOB_NAME_VARCS, theatreParty);
				break;
			case VarbitID.TOA_CLIENT_PARTYSTATUS:
				toaStatus = onPartyStatusChanged(toaStatus, value, TOA_NAME_VARCS, tombsParty);
				break;
			default:
				break;
		}
	}

	// A party member's name is blanked when they leave, so names are collected as they appear
	// rather than read once at the chest.
	public void onVarClientStrChanged(int index)
	{
		if (contains(TOB_NAME_VARCS, index))
		{
			record(theatreParty, client.getVarcStrValue(index));
		}
		else if (contains(TOA_NAME_VARCS, index))
		{
			record(tombsParty, client.getVarcStrValue(index));
		}
	}

	public void onPlayerSpawned(Player player)
	{
		if (inChambers)
		{
			record(chambersParty, player.getName());
		}
	}

	// Number of other players remembered in that raid's party, clan members or not.
	public int getPartySize(String lootSource)
	{
		Party party = partyFor(lootSource);
		if (party == null)
		{
			return 0;
		}

		String localName = localName();
		return party.names.size() - (localName != null && party.names.contains(localName) ? 1 : 0);
	}

	// The other members of that raid's party who are in the local player's clan channel, or were
	// when seen.
	public List<String> getClanMembers(String lootSource)
	{
		Party party = partyFor(lootSource);
		if (party == null)
		{
			return Collections.emptyList();
		}

		ClanChannel clanChannel = client.getClanChannel();
		String localName = localName();

		List<String> result = new ArrayList<>();
		for (String name : party.names)
		{
			if (name.equals(localName))
			{
				continue;
			}

			if (party.clanMembers.contains(name) || (clanChannel != null && clanChannel.findMember(name) != null))
			{
				result.add(name);
			}
		}
		return result;
	}

	public void reset()
	{
		chambersParty.clear();
		theatreParty.clear();
		tombsParty.clear();
		inChambers = false;
		tobStatus = 0;
		toaStatus = 0;
	}

	// Entering the raid starts a fresh party, so a member of an earlier line-up is not carried
	// into this one. Names set while the party was still forming are re-read here.
	private int onPartyStatusChanged(int previous, int value, int[] nameVarcs, Party party)
	{
		if (previous < STATUS_INSIDE && value >= STATUS_INSIDE)
		{
			party.clear();
			for (int varc : nameVarcs)
			{
				record(party, client.getVarcStrValue(varc));
			}
		}
		return value;
	}

	private void recordVisiblePlayers()
	{
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return;
		}

		for (Player player : worldView.players())
		{
			record(chambersParty, player.getName());
		}
	}

	private void record(Party party, String rawName)
	{
		if (rawName == null)
		{
			return;
		}

		// The party name varcs use non-breaking spaces, unlike Player.getName().
		String name = Text.sanitize(rawName);
		if (name.isEmpty())
		{
			return;
		}

		party.names.add(name);

		ClanChannel clanChannel = client.getClanChannel();
		if (clanChannel != null && clanChannel.findMember(name) != null)
		{
			party.clanMembers.add(name);
		}
	}

	private Party partyFor(String lootSource)
	{
		if (CHAMBERS_OF_XERIC.equals(lootSource))
		{
			return chambersParty;
		}
		if (THEATRE_OF_BLOOD.equals(lootSource))
		{
			return theatreParty;
		}
		if (TOMBS_OF_AMASCUT.equals(lootSource))
		{
			return tombsParty;
		}
		return null;
	}

	private String localName()
	{
		Player localPlayer = client.getLocalPlayer();
		return localPlayer == null ? null : localPlayer.getName();
	}

	private static boolean contains(int[] values, int value)
	{
		for (int candidate : values)
		{
			if (candidate == value)
			{
				return true;
			}
		}
		return false;
	}

	private static class Party
	{
		// Everyone seen in the party, the local player included.
		private final Set<String> names = new LinkedHashSet<>();
		// The subset that was in the clan channel when seen. Kept separately so a clanmate who
		// logs out after the raid, and so drops out of the channel, is still credited.
		private final Set<String> clanMembers = new LinkedHashSet<>();

		private void clear()
		{
			names.clear();
			clanMembers.clear();
		}
	}
}

package com.ironkinclan.manager;

import java.util.Map;

/**
 * Receives events destined for the remote logging service. Unlike {@link DiagnosticListener},
 * whose free-form text stays on the user's machine, everything passed here leaves it, so:
 * the message must be a constant (the service groups on it), the variable parts go in the
 * context, and neither may identify a player - no RuneScape names and no chat content.
 */
public interface RemoteLogListener
{
	enum Level
	{
		ERROR,
		WARN,
		INFO,
		DEBUG
	}

	// context may be null.
	void onRemoteLogEvent(Level level, String message, Map<String, Object> context);
}

package com.ironkinclan.manager;

import com.google.gson.Gson;
import com.ironkinclan.api.IronkinClanApiClient;
import com.ironkinclan.config.IronkinClanConfig;
import com.ironkinclan.manager.RemoteLogListener.Level;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Queues errors and log events in memory and sends them to the logging service in batches.
 * Opt-in (see {@link IronkinClanConfig#enableErrorReporting()}) and deliberately silent: a failure
 * to send is only ever written to {@code log.debug}, never to the panel log or chat, and never
 * fed back into this manager.
 *
 * Like {@link EmberManager}, this does not use {@link com.ironkinclan.api.RetryingCall}: a batch
 * that fails to send is dropped, except on HTTP 429 where it is kept for after the Retry-After.
 */
@Slf4j
public class RemoteLogManager
{
	// Keep in sync with "version" in runelite-plugin.properties, which isn't readable at runtime.
	static final String PLUGIN_VERSION = "1.02";
	static final String INSTALL_ID_KEY = "installId";

	// Limits imposed by the ingest endpoint. One over-long field rejects the whole batch.
	static final int MAX_EVENTS_PER_REQUEST = 50;
	static final int MAX_MESSAGE_LENGTH = 2000;
	static final int MAX_STACK_LENGTH = 16000;
	private static final int MAX_CAUSE_DEPTH = 5;
	// The endpoint allows 4,000; the margin leaves room for the "occurrences" entry added on send.
	private static final int MAX_CONTEXT_LENGTH = 3900;
	// The endpoint allows 256 KB for the whole body; the margin covers the envelope.
	private static final int MAX_BODY_BYTES = 200_000;

	static final int MAX_QUEUED_EVENTS = 200;
	private static final long FLUSH_INTERVAL_SECONDS = 30;
	private static final long DEFAULT_RETRY_AFTER_SECONDS = 60;
	private static final long MAX_RETRY_AFTER_SECONDS = 3600;

	private final IronkinClanConfig config;
	private final ConfigManager configManager;
	private final IronkinClanApiClient apiClient;
	private final OkHttpClient httpClient;
	private final Gson gson;
	private final ScheduledExecutorService executor;

	// Keyed by level + message + stack, so a repeat of an event that is still waiting to be sent
	// bumps its occurrence count instead of queueing again. Insertion order doubles as queue order.
	private final Map<String, PendingEvent> pending = new LinkedHashMap<>();
	private volatile long pausedUntilMillis;
	private ScheduledFuture<?> flushTask;

	@Inject
	public RemoteLogManager(IronkinClanConfig config, ConfigManager configManager, IronkinClanApiClient apiClient,
		OkHttpClient httpClient, Gson gson, ScheduledExecutorService executor)
	{
		this.config = config;
		this.configManager = configManager;
		this.apiClient = apiClient;
		this.httpClient = httpClient;
		this.gson = gson;
		this.executor = executor;
	}

	public void start()
	{
		cancelFlushTask();
		flushTask = executor.scheduleWithFixedDelay(this::flush, FLUSH_INTERVAL_SECONDS, FLUSH_INTERVAL_SECONDS, TimeUnit.SECONDS);
	}

	// Sends whatever is still queued on the way out. enqueue() only hands the request to the
	// OkHttp pool, so this doesn't block shutdown.
	public void stop()
	{
		cancelFlushTask();
		flush();
		synchronized (pending)
		{
			pending.clear();
		}
	}

	private void cancelFlushTask()
	{
		if (flushTask != null)
		{
			flushTask.cancel(false);
			flushTask = null;
		}
	}

	// context may be null. See RemoteLogListener for what is allowed in message and context.
	public void log(Level level, String message, Map<String, Object> context)
	{
		enqueue(level, message, null, context);
	}

	// Only for exceptions thrown from this plugin's own code. The service groups events that have
	// a stack by exception type and top frames alone, so an IOException out of OkHttp would land in
	// the same group no matter which request failed - report those with log() and the exception
	// text in the context instead.
	public void logException(String message, Throwable cause, Map<String, Object> context)
	{
		// Logged locally whether or not reporting is enabled, so the stack trace is never lost.
		log.warn(message, cause);
		enqueue(Level.ERROR, message, cause, context);
	}

	private void enqueue(Level level, String message, Throwable cause, Map<String, Object> context)
	{
		try
		{
			if (!isEnabled())
			{
				return;
			}

			PendingEvent event = new PendingEvent();
			event.level = level.name().toLowerCase(Locale.ROOT);
			event.message = truncate(message == null || message.isEmpty() ? "(no message)" : message, MAX_MESSAGE_LENGTH);
			event.stack = cause == null ? null : truncate(stackTraceOf(cause), MAX_STACK_LENGTH);
			event.context = boundedContext(context);

			String key = event.level + '\n' + event.message + '\n' + event.stack;
			synchronized (pending)
			{
				add(key, event);
			}
		}
		catch (RuntimeException e)
		{
			log.debug("Failed to queue remote log event", e);
		}
	}

	// Caller must hold the lock on pending.
	private void add(String key, PendingEvent event)
	{
		PendingEvent queued = pending.get(key);
		if (queued != null)
		{
			queued.occurrences += event.occurrences;
			return;
		}

		if (pending.size() >= MAX_QUEUED_EVENTS)
		{
			Iterator<String> oldest = pending.keySet().iterator();
			oldest.next();
			oldest.remove();
		}
		pending.put(key, event);
	}

	// Package-private (rather than private) so unit tests can trigger a send directly instead of
	// driving the scheduled task.
	void flush()
	{
		// Anything thrown out of a scheduleWithFixedDelay task silently cancels every later run.
		try
		{
			if (!isEnabled())
			{
				synchronized (pending)
				{
					pending.clear();
				}
				return;
			}

			if (System.currentTimeMillis() < pausedUntilMillis)
			{
				return;
			}

			List<PendingEvent> batch = new ArrayList<>();
			List<LogEvent> events = new ArrayList<>();
			int bodyBytes = 0;
			synchronized (pending)
			{
				Iterator<PendingEvent> it = pending.values().iterator();
				while (it.hasNext() && batch.size() < MAX_EVENTS_PER_REQUEST)
				{
					PendingEvent next = it.next();
					LogEvent event = new LogEvent(next);
					int eventBytes = gson.toJson(event).getBytes(StandardCharsets.UTF_8).length;
					if (!batch.isEmpty() && bodyBytes + eventBytes > MAX_BODY_BYTES)
					{
						break;
					}

					it.remove();
					batch.add(next);
					events.add(event);
					bodyBytes += eventBytes;
				}
			}

			if (batch.isEmpty())
			{
				return;
			}

			IngestRequest body = new IngestRequest(installId(), PLUGIN_VERSION, events);
			Request request = apiClient.newLogIngestRequest()
				.post(RequestBody.create(IronkinClanApiClient.JSON, gson.toJson(body)))
				.build();

			httpClient.newCall(request).enqueue(new Callback()
			{
				@Override
				public void onFailure(Call call, IOException e)
				{
					log.debug("Failed to send {} remote log event(s); dropping them", batch.size(), e);
				}

				@Override
				public void onResponse(Call call, Response response)
				{
					try (Response r = response)
					{
						if (r.code() == 429)
						{
							long retryAfterSeconds = retryAfterSeconds(r);
							pausedUntilMillis = System.currentTimeMillis() + TimeUnit.SECONDS.toMillis(retryAfterSeconds);
							requeue(batch);
							log.debug("Remote log service is rate limiting; holding events for {}s", retryAfterSeconds);
						}
						else if (!r.isSuccessful())
						{
							log.debug("Remote log service rejected {} event(s) with HTTP {}; dropping them", batch.size(), r.code());
						}
					}
				}
			});
		}
		catch (RuntimeException e)
		{
			log.debug("Failed to send remote log events", e);
		}
	}

	private void requeue(List<PendingEvent> batch)
	{
		synchronized (pending)
		{
			for (PendingEvent event : batch)
			{
				add(event.level + '\n' + event.message + '\n' + event.stack, event);
			}
		}
	}

	private boolean isEnabled()
	{
		return config.enableErrorReporting();
	}

	// A random ID generated once per RuneLite profile, so the service can tell installs apart
	// without being told anything about the player.
	private String installId()
	{
		String installId = configManager.getConfiguration(IronkinClanConfig.CONFIG_GROUP, INSTALL_ID_KEY);
		if (installId == null || installId.isEmpty())
		{
			installId = UUID.randomUUID().toString();
			configManager.setConfiguration(IronkinClanConfig.CONFIG_GROUP, INSTALL_ID_KEY, installId);
		}
		return installId;
	}

	private Map<String, Object> boundedContext(Map<String, Object> context)
	{
		Map<String, Object> bounded = new LinkedHashMap<>();
		if (context == null || context.isEmpty())
		{
			return bounded;
		}

		if (gson.toJson(context).length() > MAX_CONTEXT_LENGTH)
		{
			bounded.put("contextDropped", true);
		}
		else
		{
			bounded.putAll(context);
		}
		return bounded;
	}

	private static long retryAfterSeconds(Response response)
	{
		String header = response.header("Retry-After");
		if (header == null)
		{
			return DEFAULT_RETRY_AFTER_SECONDS;
		}

		try
		{
			return Math.max(1, Math.min(MAX_RETRY_AFTER_SECONDS, Long.parseLong(header.trim())));
		}
		catch (NumberFormatException e)
		{
			return DEFAULT_RETRY_AFTER_SECONDS;
		}
	}

	// The text the ingest endpoint expects in "stack": the exception, then one "\tat frame" line
	// per frame, then the same for each cause. Always \n-separated, because the service
	// fingerprints the trace line by line.
	private static String stackTraceOf(Throwable cause)
	{
		StringBuilder stack = new StringBuilder();
		Throwable current = cause;
		// Depth-limited so a cause chain that loops back on itself can't spin forever.
		for (int depth = 0; current != null && depth < MAX_CAUSE_DEPTH; depth++)
		{
			if (depth > 0)
			{
				stack.append("Caused by: ");
			}
			stack.append(current).append('\n');
			for (StackTraceElement frame : current.getStackTrace())
			{
				stack.append("\tat ").append(frame).append('\n');
			}
			current = current.getCause();
		}
		return stack.toString().trim();
	}

	private static String truncate(String text, int maxLength)
	{
		return text.length() <= maxLength ? text : text.substring(0, maxLength);
	}

	private static class PendingEvent
	{
		String level;
		String message;
		String stack;
		Map<String, Object> context;
		int occurrences = 1;
	}

	private static class LogEvent
	{
		final String level;
		final String message;
		// Left null (and so omitted from the JSON) when absent: the endpoint rejects an empty stack.
		final String stack;
		final Map<String, Object> context;

		LogEvent(PendingEvent event)
		{
			this.level = event.level;
			this.message = event.message;
			this.stack = event.stack;

			Map<String, Object> context = new LinkedHashMap<>(event.context);
			if (event.occurrences > 1)
			{
				context.put("occurrences", event.occurrences);
			}
			this.context = context.isEmpty() ? null : context;
		}
	}

	private static class IngestRequest
	{
		final String installId;
		final String pluginVersion;
		final List<LogEvent> events;

		IngestRequest(String installId, String pluginVersion, List<LogEvent> events)
		{
			this.installId = installId;
			this.pluginVersion = pluginVersion;
			this.events = events;
		}
	}
}

package com.ironkinclan.manager;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.ironkinclan.api.IronkinClanApiClient;
import com.ironkinclan.api.RequestSummary;
import com.ironkinclan.api.ResponsePreview;
import com.ironkinclan.api.RetryingCall;
import com.ironkinclan.config.IronkinClanConfig;
import com.ironkinclan.model.TrackedEventGroup;
import com.ironkinclan.model.TrackedItem;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Fetches and caches the tracked item lists for every active event returned by the server,
 * resolving item names on the client thread via {@link ItemManager}.
 */
@Slf4j
public class TrackedItemManager
{
	public interface Listener
	{
		void onTrackedItemsUpdated(List<TrackedEventGroup> events);
	}

	private final IronkinClanConfig config;
	private final IronkinClanApiClient apiClient;
	private final OkHttpClient httpClient;
	private final Gson gson;
	private final ItemManager itemManager;
	private final ClientThread clientThread;
	private final ScheduledExecutorService executor;

	@Inject
	public TrackedItemManager(IronkinClanConfig config, IronkinClanApiClient apiClient, OkHttpClient httpClient,
		Gson gson, ItemManager itemManager, ClientThread clientThread, ScheduledExecutorService executor)
	{
		this.config = config;
		this.apiClient = apiClient;
		this.httpClient = httpClient;
		this.gson = gson;
		this.itemManager = itemManager;
		this.clientThread = clientThread;
		this.executor = executor;
	}

	// eventId -> item IDs tracked by that event
	private final Map<String, Set<Integer>> eventItemIds = new ConcurrentHashMap<>();
	// itemId -> resolved name, union across all events
	private final Map<Integer, String> itemNames = new ConcurrentHashMap<>();
	private final AtomicBoolean itemListRequested = new AtomicBoolean();

	private Listener listener;
	private DiagnosticListener diagnosticListener;
	private RemoteLogListener remoteLogListener;

	public void setListener(Listener listener)
	{
		this.listener = listener;
	}

	public void setDiagnosticListener(DiagnosticListener diagnosticListener)
	{
		this.diagnosticListener = diagnosticListener;
	}

	public void setRemoteLogListener(RemoteLogListener remoteLogListener)
	{
		this.remoteLogListener = remoteLogListener;
	}

	public boolean hasTrackedItems()
	{
		return !itemNames.isEmpty();
	}

	public String getItemName(int itemId)
	{
		return itemNames.get(itemId);
	}

	public List<String> getEventIdsForItem(int itemId)
	{
		List<String> matches = new ArrayList<>();
		for (Map.Entry<String, Set<Integer>> entry : eventItemIds.entrySet())
		{
			if (entry.getValue().contains(itemId))
			{
				matches.add(entry.getKey());
			}
		}
		return matches;
	}

	public void reset()
	{
		eventItemIds.clear();
		itemNames.clear();
		itemListRequested.set(false);
	}

	public void refresh()
	{
		if (!config.enableDropTracking())
		{
			return;
		}

		itemListRequested.set(false);
		fetch();
	}

	public void fetch()
	{
		if (config.serverUrl().isEmpty())
		{
			warn("Ironkin Clan server URL is not configured; skipping tracked item list fetch");
			return;
		}

		if (config.apiKey().isEmpty())
		{
			warn("Ironkin Clan API key is not configured; skipping tracked item list fetch");
			return;
		}

		if (!itemListRequested.compareAndSet(false, true))
		{
			return;
		}

		Request request = apiClient.newItemListRequest().build();

		RetryingCall.enqueue(httpClient, executor, request, this::onRetry, new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				itemListRequested.set(false);
				warn("Failed to fetch Ironkin tracked item list: " + e.getMessage(), e);
				notifyRemote(RemoteLogListener.Level.WARN, "Failed to fetch tracked item list",
					Map.of("exception", e.toString(), "request", RequestSummary.of(request, null)));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				ItemListResponse body;
				try (Response r = response)
				{
					if (!r.isSuccessful() || r.body() == null)
					{
						itemListRequested.set(false);
						String serverResponse = ResponsePreview.of(r);
						warn("Failed to fetch Ironkin tracked item list: HTTP " + r.code() + " - server response: " + serverResponse);
						notifyRemote(RemoteLogListener.Level.WARN, "Tracked item list fetch returned an HTTP error",
							Map.of("httpStatus", r.code(), "request", RequestSummary.of(request, null), "response", serverResponse));
						return;
					}

					body = gson.fromJson(r.body().charStream(), ItemListResponse.class);
					if (body == null || body.events == null)
					{
						itemListRequested.set(false);
						warn("Ironkin tracked item list response was empty or malformed");
						// No response content here or on a parse failure: a successful item list
						// reply carries the event passwords.
						notifyRemote(RemoteLogListener.Level.WARN, "Tracked item list response was empty or malformed", null);
						return;
					}
				}
				catch (JsonSyntaxException e)
				{
					itemListRequested.set(false);
					warn("Failed to parse Ironkin tracked item list: " + e.getMessage(), e);
					notifyRemote(RemoteLogListener.Level.WARN, "Failed to parse tracked item list", Map.of("exception", e.toString()));
					return;
				}

				// The API only sends item IDs; resolve the canonical name from the client's own
				// item cache. ItemManager must be called on the client thread.
				clientThread.invoke(() ->
				{
					eventItemIds.clear();
					itemNames.clear();

					List<TrackedEventGroup> resolved = new ArrayList<>(body.events.size());
					for (EventEntry eventEntry : body.events)
					{
						List<TrackedItem> groupItems = new ArrayList<>(eventEntry.items.size());
						Set<Integer> ids = new HashSet<>();
						for (int itemId : eventEntry.items)
						{
							String name = itemManager.getItemComposition(itemId).getName();
							itemNames.put(itemId, name);
							ids.add(itemId);
							groupItems.add(new TrackedItem(itemId, name));
						}
						eventItemIds.put(eventEntry.eventId, ids);
						resolved.add(new TrackedEventGroup(eventEntry.eventId, groupItems, eventEntry.eventPassword));
					}

					if (listener != null)
					{
						listener.onTrackedItemsUpdated(resolved);
					}

					if (diagnosticListener != null)
					{
						diagnosticListener.onDiagnosticEvent(
							"Loaded " + body.events.size() + " tracked events with " + itemNames.size() + " unique items", true);
					}
				});
			}
		});
	}

	private void onRetry(String message)
	{
		if (diagnosticListener != null)
		{
			diagnosticListener.onDiagnosticEvent(message, false);
		}
	}

	private void warn(String message)
	{
		log.warn(message);
		if (diagnosticListener != null)
		{
			diagnosticListener.onDiagnosticEvent(message, false);
		}
	}

	private void warn(String message, Throwable t)
	{
		log.warn(message, t);
		if (diagnosticListener != null)
		{
			diagnosticListener.onDiagnosticEvent(message, false);
		}
	}

	private void notifyRemote(RemoteLogListener.Level level, String message, Map<String, Object> context)
	{
		if (remoteLogListener != null)
		{
			remoteLogListener.onRemoteLogEvent(level, message, context);
		}
	}

	private static class ItemListResponse
	{
		List<EventEntry> events;
	}

	private static class EventEntry
	{
		String eventId;
		List<Integer> items;
		String eventPassword;
	}
}

package com.ironkinclan.model;

import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * The bosses/activities the Ironkin Hall of Flame currently accepts personal best
 * submissions for (https://ironkinclan.com/hall-of-flame), and the NPC display name(s)
 * RuneLite reports for each one.
 * <p>
 * Matched against {@link net.runelite.api.Actor#getName()} rather than NpcID gameval
 * constants: several of these (Zulrah, Doom of Mokhaiotl) have no discoverable NpcID
 * constant even in the latest runelite-api release, while the boss's displayed name is
 * always available and naturally resilient to new NPC ID variants being added upstream.
 */
public enum BossActivity
{
	SHELLBANE_GRYPHON("Shellbane Gryphon", "Shellbane Gryphon"),
	MAD_ANGEL("Mad Angel", "Mad Angel"),
	MAGGOT_KING("Maggot King", "Maggot King"),
	// NPC name confirmed via the OSRS Wiki infobox (oldschool.runescape.wiki/w/Doom_of_Mokhaiotl):
	// ids 14707/14708/14709 for the base/shielded/burrowed forms, none yet in gameval's NpcID
	// (very new 2026 content) - all three phase names are included since the last-interacting
	// form before the kill/PB message isn't guaranteed to be the base one.
	DOOM_OF_MOKHAIOTL("Doom of Mokhaiotl (Floors 1-8)", "Doom of Mokhaiotl", "Doom of Mokhaiotl (Shielded)", "Doom of Mokhaiotl (Burrowed)"),
	ARAXXOR("Araxxor", "Araxxor"),
	AMOXLIATL("Amoxliatl", "Amoxliatl"),
	// The site's own hall-of-flame JSON API (fetched earlier) had this misspelled as
	// "Colloseum" (double L), but the live plugin-submit form's "boss" dropdown - the actual
	// submission endpoint's validation - spells it correctly. The final boss NPC is Sol Heredit.
	COLOSSEUM("Colosseum", "Sol Heredit"),
	VARDORVIS("Vardorvis", "Vardorvis"),
	WHISPERER("Whisperer", "The Whisperer", "Whisperer"),
	LEVIATHAN("Leviathan", "The Leviathan", "Leviathan"),
	DUKE_SUCELLUS("Duke Sucellus", "Duke Sucellus"),
	PHANTOM_MUSPAH("Phantom Muspah", "Phantom Muspah"),
	PHOSANIS_NIGHTMARE("Phosani's Nightmare", "Phosani's Nightmare"),
	// Gauntlet and Corrupted Gauntlet have distinctly-named final bosses, so no NPC ID
	// disambiguation is needed between the two.
	CORRUPTED_GAUNTLET("Corrupted Gauntlet", "Corrupted Hunllef"),
	GAUNTLET("Gauntlet", "Crystalline Hunllef"),
	ALCHEMICAL_HYDRA("Alchemical Hydra", "Alchemical Hydra"),
	HESPORI("Hespori", "Hespori"),
	VORKATH("Vorkath", "Vorkath"),
	GROTESQUE_GUARDIANS("Grotesque Guardians", "Dawn", "Dusk"),
	INFERNO("Inferno", "TzKal-Zuk"),
	ZULRAH("Zulrah", "Zulrah"),
	FIGHT_CAVES("Fight Caves", "TzTok-Jad");

	// The exact string to send in the "boss" field of a Hall of Flame submission - must
	// match the site's category name verbatim.
	public final String hallOfFlameName;
	private final Set<String> npcNames;

	// Built once all constants exist, rather than scanning every activity's npcNames on every
	// lookup - this runs on every InteractingChanged involving the local player, so it's worth
	// being an O(1) map lookup instead of an O(n*m) scan, even though neither is noticeable at
	// this scale.
	private static final Map<String, BossActivity> BY_NPC_NAME = new HashMap<>();

	static
	{
		for (BossActivity activity : values())
		{
			for (String npcName : activity.npcNames)
			{
				BY_NPC_NAME.put(npcName.toLowerCase(), activity);
			}
		}
	}

	BossActivity(String hallOfFlameName, String... npcNames)
	{
		this.hallOfFlameName = hallOfFlameName;
		this.npcNames = new HashSet<>(Arrays.asList(npcNames));
	}

	/**
	 * @return the activity whose NPC name(s) match {@code npcName} (case-insensitive), or
	 * {@code null} if the name isn't recognized.
	 */
	public static BossActivity forNpcName(String npcName)
	{
		return npcName == null ? null : BY_NPC_NAME.get(npcName.toLowerCase());
	}

	/**
	 * An additional phrase (case-insensitive) that must also appear in the chat message for a
	 * "(new personal best)" detection to actually count for this activity - {@code null} if the
	 * generic marker alone is sufficient (true for every activity except the one below).
	 * <p>
	 * Needed because Doom of Mokhaiotl reports more than one kind of personal best in the same
	 * chat stream: a PB per individual delve level (e.g. "Delve level 5 duration: 0:50 (new
	 * personal best)") *and* a separate PB for the full floors 1-8 run ("Delve level 1 - 8
	 * duration: 9:04 (new personal best)") - confirmed in-game. Only the latter matches this
	 * Hall of Flame category; without this check, a per-level PB would get wrongly submitted as
	 * the floors-1-8 record.
	 */
	public String requiredMessagePhrase()
	{
		return this == DOOM_OF_MOKHAIOTL ? "level 1 - 8 duration" : null;
	}
}

