package com.ironkinclan.manager;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.ironkinclan.api.IronkinClanApiClient;
import com.ironkinclan.config.IronkinClanConfig;
import com.ironkinclan.manager.RemoteLogListener.Level;
import java.io.IOException;
import java.util.Collections;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import net.runelite.client.config.ConfigManager;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.Buffer;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.atLeast;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class RemoteLogManagerTest
{
	private IronkinClanConfig config;
	private ConfigManager configManager;
	private OkHttpClient httpClient;
	private Call call;
	private RemoteLogManager manager;

	@Before
	public void setUp()
	{
		config = mock(IronkinClanConfig.class);
		when(config.serverUrl()).thenReturn("https://ironkin.example.com");
		when(config.apiKey()).thenReturn("secret-key");
		when(config.enableErrorReporting()).thenReturn(true);

		configManager = mock(ConfigManager.class);
		when(configManager.getConfiguration(IronkinClanConfig.CONFIG_GROUP, RemoteLogManager.INSTALL_ID_KEY))
			.thenReturn("install-1");

		httpClient = mock(OkHttpClient.class);
		call = mock(Call.class);
		when(httpClient.newCall(any(Request.class))).thenReturn(call);

		manager = new RemoteLogManager(config, configManager, new IronkinClanApiClient(config), httpClient,
			new Gson(), mock(ScheduledExecutorService.class));
	}

	private void respondWith(int code, String retryAfter)
	{
		doAnswer(invocation ->
		{
			Callback callback = invocation.getArgument(0);
			Response.Builder response = new Response.Builder()
				.request(new Request.Builder().url("https://logs.example.com/api/ingest").build())
				.protocol(Protocol.HTTP_1_1)
				.code(code)
				.message("")
				.body(ResponseBody.create(MediaType.get("application/json"), "{}"));
			if (retryAfter != null)
			{
				response.header("Retry-After", retryAfter);
			}
			callback.onResponse(call, response.build());
			return null;
		}).when(call).enqueue(any(Callback.class));
	}

	private Request sentRequest(int index)
	{
		ArgumentCaptor<Request> requestCaptor = ArgumentCaptor.forClass(Request.class);
		verify(httpClient, atLeast(index + 1)).newCall(requestCaptor.capture());
		return requestCaptor.getAllValues().get(index);
	}

	private JsonObject sentBody(int index) throws IOException
	{
		Buffer buffer = new Buffer();
		sentRequest(index).body().writeTo(buffer);
		return new Gson().fromJson(buffer.readUtf8(), JsonObject.class);
	}

	@Test
	public void flush_postsQueuedEventsToIngestUrlWithoutApiKey() throws IOException
	{
		manager.log(Level.WARN, "Failed to fetch ember balance", Map.of("httpStatus", 503));
		manager.flush();

		Request request = sentRequest(0);
		assertEquals("POST", request.method());
		assertEquals(IronkinClanApiClient.LOG_SERVICE_URL + "/api/ingest", request.url().toString());
		assertNull(request.header(IronkinClanApiClient.API_KEY_HEADER));
		assertNull(request.header(IronkinClanApiClient.PLUGIN_KEY_HEADER));

		JsonObject body = sentBody(0);
		assertEquals("install-1", body.get("installId").getAsString());
		assertEquals(RemoteLogManager.PLUGIN_VERSION, body.get("pluginVersion").getAsString());

		JsonArray events = body.getAsJsonArray("events");
		assertEquals(1, events.size());
		JsonObject event = events.get(0).getAsJsonObject();
		assertEquals("warn", event.get("level").getAsString());
		assertEquals("Failed to fetch ember balance", event.get("message").getAsString());
		assertEquals(503, event.getAsJsonObject("context").get("httpStatus").getAsInt());
		// The endpoint rejects an empty stack, so it has to be absent rather than "" or null.
		assertFalse(event.has("stack"));
	}

	@Test
	public void flush_nothingQueued_sendsNothing()
	{
		manager.flush();

		verify(httpClient, never()).newCall(any(Request.class));
	}

	@Test
	public void log_whenReportingDisabled_queuesNothing()
	{
		when(config.enableErrorReporting()).thenReturn(false);
		manager.log(Level.ERROR, "Failed to upload drop", null);

		when(config.enableErrorReporting()).thenReturn(true);
		manager.flush();

		verify(httpClient, never()).newCall(any(Request.class));
	}

	@Test
	public void flush_whenReportingDisabledAfterQueueing_discardsQueue()
	{
		manager.log(Level.ERROR, "Failed to upload drop", null);

		when(config.enableErrorReporting()).thenReturn(false);
		manager.flush();
		when(config.enableErrorReporting()).thenReturn(true);
		manager.flush();

		verify(httpClient, never()).newCall(any(Request.class));
	}

	@Test
	public void flush_generatesAndStoresInstallIdWhenMissing() throws IOException
	{
		when(configManager.getConfiguration(IronkinClanConfig.CONFIG_GROUP, RemoteLogManager.INSTALL_ID_KEY))
			.thenReturn(null);

		manager.log(Level.INFO, "Plugin started", null);
		manager.flush();

		ArgumentCaptor<String> idCaptor = ArgumentCaptor.forClass(String.class);
		verify(configManager).setConfiguration(eq(IronkinClanConfig.CONFIG_GROUP), eq(RemoteLogManager.INSTALL_ID_KEY), idCaptor.capture());
		assertEquals(36, idCaptor.getValue().length());
		assertEquals(idCaptor.getValue(), sentBody(0).get("installId").getAsString());
	}

	@Test
	public void flush_existingInstallId_isNotRegenerated()
	{
		manager.log(Level.INFO, "Plugin started", null);
		manager.flush();

		verify(configManager, never()).setConfiguration(anyString(), anyString(), anyString());
	}

	@Test
	public void log_repeatedEvent_isSentOnceWithOccurrenceCount() throws IOException
	{
		for (int i = 0; i < 5; i++)
		{
			manager.log(Level.WARN, "Failed to fetch ember balance", Map.of("httpStatus", 503));
		}
		manager.flush();

		JsonArray events = sentBody(0).getAsJsonArray("events");
		assertEquals(1, events.size());
		JsonObject context = events.get(0).getAsJsonObject().getAsJsonObject("context");
		assertEquals(5, context.get("occurrences").getAsInt());
		assertEquals(503, context.get("httpStatus").getAsInt());
	}

	@Test
	public void logException_sendsStackTraceWithUnixLineEndings() throws IOException
	{
		manager.logException("Unexpected error while processing loot",
			new IllegalStateException("boom", new IOException("root cause")), null);
		manager.flush();

		JsonObject event = sentBody(0).getAsJsonArray("events").get(0).getAsJsonObject();
		assertEquals("error", event.get("level").getAsString());
		String stack = event.get("stack").getAsString();
		assertTrue(stack.startsWith("java.lang.IllegalStateException: boom\n\tat "));
		assertTrue(stack.contains("\nCaused by: java.io.IOException: root cause\n\tat "));
		assertFalse(stack.contains("\r"));
	}

	@Test
	public void log_overLongFields_areTruncatedToEndpointLimits() throws IOException
	{
		String longText = String.join("", Collections.nCopies(20000, "x"));
		manager.logException(longText, new IllegalStateException(longText), Map.of("detail", longText));
		manager.flush();

		JsonObject event = sentBody(0).getAsJsonArray("events").get(0).getAsJsonObject();
		assertEquals(RemoteLogManager.MAX_MESSAGE_LENGTH, event.get("message").getAsString().length());
		assertEquals(RemoteLogManager.MAX_STACK_LENGTH, event.get("stack").getAsString().length());
		assertTrue(event.getAsJsonObject("context").get("contextDropped").getAsBoolean());
		assertFalse(event.getAsJsonObject("context").has("detail"));
	}

	@Test
	public void flush_sendsAtMostFiftyEventsPerRequest() throws IOException
	{
		for (int i = 0; i < 60; i++)
		{
			manager.log(Level.INFO, "event " + i, null);
		}

		manager.flush();
		manager.flush();

		assertEquals(RemoteLogManager.MAX_EVENTS_PER_REQUEST, sentBody(0).getAsJsonArray("events").size());
		assertEquals(10, sentBody(1).getAsJsonArray("events").size());
	}

	@Test
	public void flush_keepsRequestBodyUnderEndpointLimit() throws IOException
	{
		String stackSizedMessage = String.join("", Collections.nCopies(17000, "x"));
		for (int i = 0; i < 30; i++)
		{
			manager.logException("event " + i, new IllegalStateException(stackSizedMessage), null);
		}

		manager.flush();

		Buffer buffer = new Buffer();
		sentRequest(0).body().writeTo(buffer);
		assertTrue(buffer.size() < 256 * 1024);
	}

	@Test
	public void log_queueFull_dropsOldestEvents() throws IOException
	{
		for (int i = 0; i < RemoteLogManager.MAX_QUEUED_EVENTS + 10; i++)
		{
			manager.log(Level.INFO, "event " + i, null);
		}

		manager.flush();

		JsonArray events = sentBody(0).getAsJsonArray("events");
		assertEquals("event 10", events.get(0).getAsJsonObject().get("message").getAsString());
	}

	@Test
	public void flush_rateLimited_holdsBatchUntilRetryAfter()
	{
		respondWith(429, "60");
		manager.log(Level.ERROR, "Failed to upload drop", null);

		manager.flush();
		manager.flush();

		// The second flush is inside the Retry-After window, so it must not hit the service again.
		verify(httpClient, times(1)).newCall(any(Request.class));
	}

	@Test
	public void flush_serverError_dropsBatch()
	{
		respondWith(500, null);
		manager.log(Level.ERROR, "Failed to upload drop", null);

		manager.flush();
		manager.flush();

		verify(httpClient, times(1)).newCall(any(Request.class));
	}
}

package com.ironkinclan.manager;

import com.google.gson.Gson;
import com.ironkinclan.api.IronkinClanApiClient;
import com.ironkinclan.config.IronkinClanConfig;
import com.ironkinclan.model.TrackedEventGroup;
import java.io.IOException;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import net.runelite.api.ItemComposition;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.contains;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.ArgumentMatchers.startsWith;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class TrackedItemManagerTest
{
	private IronkinClanConfig config;
	private OkHttpClient httpClient;
	private ItemManager itemManager;
	private ClientThread clientThread;
	private ScheduledExecutorService executor;
	private Call call;
	private TrackedItemManager manager;

	private DiagnosticListener diagnosticListener;
	private TrackedItemManager.Listener listener;

	@Before
	public void setUp()
	{
		config = mock(IronkinClanConfig.class);
		when(config.serverUrl()).thenReturn("https://ironkin.example.com");
		when(config.apiKey()).thenReturn("secret-key");

		IronkinClanApiClient apiClient = new IronkinClanApiClient(config);
		httpClient = mock(OkHttpClient.class);
		itemManager = mock(ItemManager.class);
		clientThread = mock(ClientThread.class);
		call = mock(Call.class);

		// fetch() resolves item names inside clientThread.invoke(); run it synchronously so
		// tests can assert on the result immediately.
		doAnswer(invocation ->
		{
			Runnable runnable = invocation.getArgument(0);
			runnable.run();
			return null;
		}).when(clientThread).invoke(any(Runnable.class));

		when(httpClient.newCall(any(Request.class))).thenReturn(call);

		executor = mock(ScheduledExecutorService.class);
		// Run scheduled retries synchronously and immediately so tests don't need to deal with
		// real delays - the backoff duration itself isn't the concern of these tests.
		doAnswer(invocation ->
		{
			Runnable retry = invocation.getArgument(0);
			retry.run();
			return null;
		}).when(executor).schedule(any(Runnable.class), anyLong(), any(TimeUnit.class));

		manager = new TrackedItemManager(config, apiClient, httpClient, new Gson(), itemManager, clientThread, executor);

		diagnosticListener = mock(DiagnosticListener.class);
		listener = mock(TrackedItemManager.Listener.class);
		manager.setDiagnosticListener(diagnosticListener);
		manager.setListener(listener);

		nameItem(20997, "Twisted bow");
		nameItem(11840, "Dragon warhammer");
	}

	private void nameItem(int itemId, String name)
	{
		ItemComposition composition = mock(ItemComposition.class);
		when(composition.getName()).thenReturn(name);
		when(itemManager.getItemComposition(itemId)).thenReturn(composition);
	}

	private void respondWithSuccess(String json)
	{
		respondWith(200, json);
	}

	private void respondWith(int code, String body)
	{
		doAnswer(invocation ->
		{
			Callback callback = invocation.getArgument(0);
			Response response = new Response.Builder()
				.request(new Request.Builder().url("https://ironkin.example.com/events/item-list").build())
				.protocol(Protocol.HTTP_1_1)
				.code(code)
				.message(code == 200 ? "OK" : "Error")
				.body(ResponseBody.create(MediaType.get("application/json; charset=utf-8"), body))
				.build();
			callback.onResponse(call, response);
			return null;
		}).when(call).enqueue(any(Callback.class));
	}

	private void respondWithFailure(IOException exception)
	{
		doAnswer(invocation ->
		{
			Callback callback = invocation.getArgument(0);
			callback.onFailure(call, exception);
			return null;
		}).when(call).enqueue(any(Callback.class));
	}

	@Test
	public void fetch_missingServerUrl_skipsRequestAndNotifiesDiagnostic()
	{
		when(config.serverUrl()).thenReturn("");

		manager.fetch();

		verify(httpClient, never()).newCall(any(Request.class));
		verify(diagnosticListener).onDiagnosticEvent(anyString(), eq(false));
	}

	@Test
	public void fetch_missingApiKey_skipsRequestAndNotifiesDiagnostic()
	{
		when(config.apiKey()).thenReturn("");

		manager.fetch();

		verify(httpClient, never()).newCall(any(Request.class));
		verify(diagnosticListener).onDiagnosticEvent(anyString(), eq(false));
	}

	@Test
	@SuppressWarnings("unchecked")
	public void fetch_successfulResponse_populatesTrackedItemsAndNotifiesListener()
	{
		respondWithSuccess("{ \"events\": ["
			+ "{ \"eventId\": \"bounty-123\", \"items\": [20997] },"
			+ "{ \"eventId\": \"botw-123\", \"items\": [11840, 20997] }"
			+ "] }");

		manager.fetch();

		assertTrue(manager.hasTrackedItems());
		assertEquals("Twisted bow", manager.getItemName(20997));
		assertEquals("Dragon warhammer", manager.getItemName(11840));

		ArgumentCaptor<List<TrackedEventGroup>> captor = ArgumentCaptor.forClass(List.class);
		verify(listener).onTrackedItemsUpdated(captor.capture());
		assertEquals(2, captor.getValue().size());
	}

	@Test
	@SuppressWarnings("unchecked")
	public void fetch_eventWithPassword_populatesEventPasswordOnGroup()
	{
		respondWithSuccess("{ \"events\": ["
			+ "{ \"eventId\": \"bounty-123\", \"items\": [20997], \"eventPassword\": \"ironkin-password\" },"
			+ "{ \"eventId\": \"botw-123\", \"items\": [11840] }"
			+ "] }");

		manager.fetch();

		ArgumentCaptor<List<TrackedEventGroup>> captor = ArgumentCaptor.forClass(List.class);
		verify(listener).onTrackedItemsUpdated(captor.capture());

		List<TrackedEventGroup> events = captor.getValue();
		assertEquals("ironkin-password", events.get(0).eventPassword);
		assertNull(events.get(1).eventPassword);
	}

	@Test
	public void fetch_itemTrackedByMultipleEvents_getEventIdsForItemReturnsBoth()
	{
		respondWithSuccess("{ \"events\": ["
			+ "{ \"eventId\": \"bounty-123\", \"items\": [20997] },"
			+ "{ \"eventId\": \"botw-123\", \"items\": [11840, 20997] }"
			+ "] }");

		manager.fetch();

		List<String> eventIds = manager.getEventIdsForItem(20997);
		assertEquals(2, eventIds.size());
		assertTrue(eventIds.contains("bounty-123"));
		assertTrue(eventIds.contains("botw-123"));
		assertEquals(Collections.singletonList("botw-123"), manager.getEventIdsForItem(11840));
	}

	@Test
	public void fetch_itemNotTracked_getEventIdsForItemReturnsEmpty()
	{
		respondWithSuccess("{ \"events\": [ { \"eventId\": \"bounty-123\", \"items\": [20997] } ] }");

		manager.fetch();

		assertTrue(manager.getEventIdsForItem(999).isEmpty());
	}

	@Test
	public void fetch_httpError_notifiesDiagnosticAndAllowsRetry()
	{
		respondWith(500, "");

		manager.fetch();

		verify(diagnosticListener).onDiagnosticEvent(anyString(), eq(false));
		assertFalse(manager.hasTrackedItems());

		// A failed fetch should reset the in-flight flag so a subsequent fetch is allowed.
		respondWithSuccess("{ \"events\": [ { \"eventId\": \"bounty-123\", \"items\": [20997] } ] }");
		manager.fetch();

		assertTrue(manager.hasTrackedItems());
	}

	@Test
	public void fetch_emptyResponseBody_notifiesDiagnosticWithoutCrashing()
	{
		respondWithSuccess("");

		manager.fetch();

		verify(diagnosticListener).onDiagnosticEvent(anyString(), eq(false));
		assertFalse(manager.hasTrackedItems());
	}

	@Test
	public void fetch_responseWrongJsonType_notifiesDiagnosticWithoutCrashing()
	{
		// Valid JSON, but the wrong shape (array instead of object) - triggers Gson's
		// JsonSyntaxException path rather than the "empty/malformed" null-body path.
		respondWithSuccess("[1, 2, 3]");

		manager.fetch();

		verify(diagnosticListener).onDiagnosticEvent(anyString(), eq(false));
		assertFalse(manager.hasTrackedItems());
	}

	@Test
	public void fetch_emptyEventsList_treatsAsEmptyTrackedItems()
	{
		respondWithSuccess("{ \"events\": [] }");

		manager.fetch();

		assertFalse(manager.hasTrackedItems());
		verify(listener).onTrackedItemsUpdated(Collections.emptyList());
	}

	@Test
	public void fetch_networkFailure_retriesTwiceThenNotifiesDiagnostic()
	{
		respondWithFailure(new IOException("boom"));

		manager.fetch();

		// Initial attempt + 2 retries.
		verify(httpClient, times(3)).newCall(any(Request.class));
		// One notice per retry, then the single terminal failure.
		verify(diagnosticListener, times(2)).onDiagnosticEvent(contains("retrying in"), eq(false));
		verify(diagnosticListener).onDiagnosticEvent(startsWith("Failed to fetch"), eq(false));
		assertFalse(manager.hasTrackedItems());
	}

	@Test
	public void fetch_networkFailure_retriesWithIncreasingBackoff()
	{
		respondWithFailure(new IOException("boom"));

		manager.fetch();

		ArgumentCaptor<Long> delayCaptor = ArgumentCaptor.forClass(Long.class);
		verify(executor, times(2)).schedule(any(Runnable.class), delayCaptor.capture(), eq(TimeUnit.MILLISECONDS));
		assertEquals(2000L, (long) delayCaptor.getAllValues().get(0));
		assertEquals(4000L, (long) delayCaptor.getAllValues().get(1));
	}

	@Test
	public void fetch_networkFailureThenSuccessOnRetry_populatesTrackedItems()
	{
		// Fail on the first attempt, then succeed on the retry.
		doAnswer(invocation ->
		{
			Callback callback = invocation.getArgument(0);
			callback.onFailure(call, new IOException("boom"));
			return null;
		}).doAnswer(invocation ->
		{
			Callback callback = invocation.getArgument(0);
			Response response = new Response.Builder()
				.request(new Request.Builder().url("https://ironkin.example.com/events/item-list").build())
				.protocol(Protocol.HTTP_1_1)
				.code(200)
				.message("OK")
				.body(ResponseBody.create(MediaType.get("application/json; charset=utf-8"),
					"{ \"events\": [ { \"eventId\": \"bounty-123\", \"items\": [20997] } ] }"))
				.build();
			callback.onResponse(call, response);
			return null;
		}).when(call).enqueue(any(Callback.class));

		manager.fetch();

		verify(httpClient, times(2)).newCall(any(Request.class));
		assertTrue(manager.hasTrackedItems());
		// The failed first attempt is surfaced as a retry notice, but a recovered fetch must not
		// also report the terminal "Failed to fetch" warning.
		verify(diagnosticListener).onDiagnosticEvent(contains("retrying in 2000ms (attempt 1/2)"), eq(false));
		verify(diagnosticListener, never()).onDiagnosticEvent(startsWith("Failed to fetch"), eq(false));
	}

	@Test
	public void fetch_whileRequestInFlight_doesNotIssueSecondCall()
	{
		// Deliberately leave call.enqueue(...) unstubbed (a no-op) to simulate a request that
		// hasn't completed yet.
		manager.fetch();
		manager.fetch();

		verify(httpClient, times(1)).newCall(any(Request.class));
	}

	@Test
	public void reset_clearsTrackedState()
	{
		respondWithSuccess("{ \"events\": [ { \"eventId\": \"bounty-123\", \"items\": [20997] } ] }");
		manager.fetch();
		assertTrue(manager.hasTrackedItems());

		manager.reset();

		assertFalse(manager.hasTrackedItems());
		assertTrue(manager.getEventIdsForItem(20997).isEmpty());
	}
}

package com.ironkinclan.model;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class BossActivityTest
{
	@Test
	public void requiredMessagePhrase_doomOfMokhaiotl_requiresFloors1To8Phrase()
	{
		assertEquals("level 1 - 8 duration", BossActivity.DOOM_OF_MOKHAIOTL.requiredMessagePhrase());
	}

	@Test
	public void requiredMessagePhrase_everyOtherActivity_isNull()
	{
		for (BossActivity activity : BossActivity.values())
		{
			if (activity == BossActivity.DOOM_OF_MOKHAIOTL)
			{
				continue;
			}

			assertNull(activity + " should not require an extra message phrase", activity.requiredMessagePhrase());
		}
	}

	@Test
	public void forNpcName_doomOfMokhaiotl_matchesAllThreePhaseNames()
	{
		assertEquals(BossActivity.DOOM_OF_MOKHAIOTL, BossActivity.forNpcName("Doom of Mokhaiotl"));
		assertEquals(BossActivity.DOOM_OF_MOKHAIOTL, BossActivity.forNpcName("Doom of Mokhaiotl (Shielded)"));
		assertEquals(BossActivity.DOOM_OF_MOKHAIOTL, BossActivity.forNpcName("Doom of Mokhaiotl (Burrowed)"));
	}

	@Test
	public void perLevelPersonalBestMessage_doesNotContainRequiredPhrase()
	{
		// Confirmed in-game: a single delve level's PB does not contain the floors-1-8 phrase.
		String perLevelMessage = "Delve level 5 duration: 0:50 (new personal best)";
		assertTrue(!perLevelMessage.toLowerCase().contains(BossActivity.DOOM_OF_MOKHAIOTL.requiredMessagePhrase()));
	}

	@Test
	public void fullRunPersonalBestMessage_containsRequiredPhrase()
	{
		// Confirmed in-game: the floors-1-8 aggregate PB message does contain the phrase.
		String fullRunMessage = "Delve level 1 - 8 duration: 9:04 (new personal best)";
		assertTrue(fullRunMessage.toLowerCase().contains(BossActivity.DOOM_OF_MOKHAIOTL.requiredMessagePhrase()));
	}
}
